// Avoid duplicating the button on re-runs
if (element.querySelector('#ext-preferences-link')) return;

const prefLink = document.createElement('div');
prefLink.className = 'global-action__item';
prefLink.id = 'ext-preferences-link';
prefLink.style.cssText = 'display:flex; align-items:center;';

const anchor = document.createElement('a');
anchor.href = 'https://community.fandom.com/wiki/Special:Preferences';
anchor.className = 'wds-button wds-is-secondary global-action__link';
anchor.setAttribute('aria-label', 'Preferences');
anchor.setAttribute('data-tracking-label', 'account.preferences');
anchor.style.cssText = [
  'display: inline-flex',
  'align-items: center',
  'gap: 6px',
  'background: linear-gradient(135deg, #00b4d8, #0077b6)',
  'color: #fff',
  'border: none',
  'font-weight: 700',
  'letter-spacing: 0.03em',
  'padding: 0 16px',
  'height: 36px',
  'border-radius: 4px',
  'font-size: 14px',
  'text-decoration: none',
  'box-shadow: 0 2px 8px rgba(0,119,182,0.45)',
  'transition: filter 0.15s ease, box-shadow 0.15s ease',
  'white-space: nowrap',
].join(';');

// Gear SVG icon (inline, no external dependency)
const svgNS = 'http://www.w3.org/2000/svg';
const svg = document.createElementNS(svgNS, 'svg');
svg.setAttribute('xmlns', svgNS);
svg.setAttribute('viewBox', '0 0 20 20');
svg.setAttribute('width', '16');
svg.setAttribute('height', '16');
svg.setAttribute('fill', 'currentColor');
svg.setAttribute('aria-hidden', 'true');
svg.style.flexShrink = '0';

const path = document.createElementNS(svgNS, 'path');
path.setAttribute('d', [
  'M10 13a3 3 0 1 0 0-6 3 3 0 0 0 0 6z',
  'M17.07 11.47l1.2-.98a1 1 0 0 0 .23-1.28l-1.5-2.6a1 1 0 0 0-1.22-.44l-1.42.57',
  'a7.1 7.1 0 0 0-1.13-.65l-.21-1.5A1 1 0 0 0 12 4h-3a1 1 0 0 0-.99.86l-.22 1.5',
  'a7.1 7.1 0 0 0-1.13.65l-1.42-.57a1 1 0 0 0-1.22.44l-1.5 2.6a1 1 0 0 0 .23 1.28l1.2.98',
  'A7.22 7.22 0 0 0 4 12c0 .18.01.35.03.53l-1.2.98a1 1 0 0 0-.23 1.28l1.5 2.6',
  'a1 1 0 0 0 1.22.44l1.42-.57c.36.24.74.45 1.13.65l.22 1.5A1 1 0 0 0 9 20h3',
  'a1 1 0 0 0 .99-.86l.21-1.5c.4-.2.77-.4 1.13-.65l1.42.57a1 1 0 0 0 1.22-.44l1.5-2.6',
  'a1 1 0 0 0-.23-1.28l-1.2-.98c.02-.18.03-.35.03-.53s-.01-.35-.03-.53z',
].join(' '));
svg.appendChild(path);

const label = document.createElement('span');
label.textContent = 'Preferences';

anchor.appendChild(svg);
anchor.appendChild(label);

// Hover effects via pointer events
anchor.addEventListener('mouseenter', function() {
  this.style.filter = 'brightness(1.15)';
  this.style.boxShadow = '0 4px 14px rgba(0,119,182,0.6)';
});
anchor.addEventListener('mouseleave', function() {
  this.style.filter = 'brightness(1)';
  this.style.boxShadow = '0 2px 8px rgba(0,119,182,0.45)';
});

prefLink.appendChild(anchor);

// Insert BEFORE the sign-in button (first child), so it appears left-most
element.insertBefore(prefLink, element.firstChild);
